UPDATE artist
artist_name = #{artistName}, introduction = #{introduction}, gender = #{gender}, country = #{country}, artist_cover = #{artistCover}, enrich_source = #{enrichSource}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE album
album_name = #{albumName}, album_type = #{albumType}, album_year = #{albumYear}, introduction = #{introduction}, company = #{company}, language = #{language}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE style
