WHERE id = #{id}

mapper.insert:
MERGE INTO song AS t USING (VALUES
(#{item.title}, #{item.filePath}, #{item.fileName}, #{item.fileFormat}, #{item.fileSize}, #{item.fileHash}, #{item.fingerprint}, #{item.duration}, #{item.coverPath}, #{item.year}, #{item.bitrate}, #{item.sampleRate}, #{item.channels}, #{item.bitsPerSample}, #{item.language}, #{item.albumId}, #{item.trackNumber}, #{item.discNumber}, #{item.trackGain}, #{item.trackPeak}, #{item.composer}, #{item.lyricist}, #{item.arranger}, #{item.producer}, #{item.extraTags}, #{item.sortTitle}, #{item.fileMtime})
) AS s(title, file_path, file_name, file_format, file_size, file_hash, fingerprint, duration, cover_path, "year", bitrate, sample_rate, channels, bits_per_sample, language, album_id, track_number, disc_number, track_gain, track_peak, composer, lyricist, arranger, producer, extra_tags, sort_title, file_mtime) ON t.file_path = s.file_path WHEN MATCHED THEN UPDATE SET title = CASE WHEN s.title IS NOT NULL THEN s.title ELSE t.title END, file_name = CASE WHEN s.file_name IS NOT NULL THEN s.file_name ELSE t.file_name END, file_format = CASE WHEN s.file_format IS NOT NULL THEN s.file_format ELSE t.file_format END, file_size = CASE WHEN s.file_size IS NOT NULL THEN s.file_size ELSE t.file_size END, file_hash = CASE WHEN s.file_hash IS NOT NULL THEN s.file_hash ELSE t.file_hash END, fingerprint = CASE WHEN s.fingerprint IS NOT NULL THEN s.fingerprint ELSE t.fingerprint END, duration = CASE WHEN s.duration IS NOT NULL THEN s.duration ELSE t.duration END, cover_path = CASE WHEN s.cover_path IS NOT NULL THEN s.cover_path ELSE t.cover_path END, "year" = CASE WHEN s."year" IS NOT NULL THEN s."year" ELSE t."year" END, bitrate = CASE WHEN s.bitrate IS NOT NULL THEN s.bitrate ELSE t.bitrate END, sample_rate = CASE WHEN s.sample_rate IS NOT NULL THEN s.sample_rate ELSE t.sample_rate END, channels = CASE WHEN s.channels IS NOT NULL THEN s.channels ELSE t.channels END, bits_per_sample = CASE WHEN s.bits_per_sample IS NOT NULL THEN s.bits_per_sample ELSE t.bits_per_sample END, language = CASE WHEN s.language IS NOT NULL THEN s.language ELSE t.language END, album_id = CASE WHEN s.album_id IS NOT NULL THEN s.album_id ELSE t.album_id END, track_number = CASE WHEN s.track_number IS NOT NULL THEN s.track_number ELSE t.track_number END, disc_number = CASE WHEN s.disc_number IS NOT NULL THEN s.disc_number ELSE t.disc_number END, track_gain = CASE WHEN s.track_gain IS NOT NULL THEN s.track_gain ELSE t.track_gain END, track_peak = CASE WHEN s.track_peak IS NOT NULL THEN s.track_peak ELSE t.track_peak END, composer = CASE WHEN s.composer IS NOT NULL THEN s.composer ELSE t.composer END, lyricist = CASE WHEN s.lyricist IS NOT NULL THEN s.lyricist ELSE t.lyricist END, arranger = CASE WHEN s.arranger IS NOT NULL THEN s.arranger ELSE t.arranger END, producer = CASE WHEN s.producer IS NOT NULL THEN s.producer ELSE t.producer END, extra_tags = CASE WHEN s.extra_tags IS NOT NULL THEN s.extra_tags ELSE t.extra_tags END, sort_title = CASE WHEN s.sort_title IS NOT NULL THEN s.sort_title ELSE t.sort_title END, file_mtime = CASE WHEN s.file_mtime IS NOT NULL THEN s.file_mtime ELSE t.file_mtime END, update_time = CURRENT_TIMESTAMP WHEN NOT MATCHED THEN INSERT (title, file_path, file_name, file_format, file_size, file_hash, fingerprint, duration, cover_path, "year", bitrate, sample_rate, channels, bits_per_sample, language, album_id, track_number, disc_number, track_gain, track_peak, composer, lyricist, arranger, producer, extra_tags, sort_title, file_mtime, update_time) VALUES (s.title, s.file_path, s.file_name, s.file_format, s.file_size, s.file_hash, s.fingerprint, s.duration, s.cover_path, s."year", s.bitrate, s.sample_rate, s.channels, s.bits_per_sample, s.language, s.album_id, s.track_number, s.disc_number, s.track_gain, s.track_peak, s.composer, s.lyricist, s.arranger, s.producer, s.extra_tags, s.sort_title, s.file_mtime, CURRENT_TIMESTAMP)

mapper.select:
SELECT s.file_path AS filePath, s.title AS TITLE, s.duration AS DURATION, GROUP_CONCAT(DISTINCT a.artist_name ORDER BY sa.sort_order SEPARATOR ',') AS ARTISTNAMES, al.album_name AS ALBUMNAME FROM song s LEFT JOIN song_artist sa ON s.id = sa.song_id LEFT JOIN artist a ON sa.artist_id = a.id LEFT JOIN album al ON s.album_id = al.id WHERE s.file_path IN
#{p}
GROUP BY s.id

SELECT s.file_path AS FILEPATH, s.title AS TITLE, s.file_name AS FILE_NAME, s.file_format AS FILE_FORMAT, s.file_size AS FILE_SIZE, s.file_hash AS FILE_HASH, s.fingerprint AS FINGERPRINT, s.duration AS DURATION, s.cover_path AS COVER_PATH, s."year" AS "YEAR", s.bitrate AS BITRATE, s.sample_rate AS SAMPLE_RATE, s.channels AS CHANNELS, s.bits_per_sample AS BITS_PER_SAMPLE, s.language AS LANGUAGE, s.album_id AS ALBUM_ID, s.track_number AS TRACK_NUMBER, s.disc_number AS DISC_NUMBER, s.track_gain AS TRACK_GAIN, s.track_peak AS TRACK_PEAK, s.composer AS COMPOSER, s.lyricist AS LYRICIST, s.arranger AS ARRANGER, s.producer AS PRODUCER, s.file_mtime AS FILE_MTIME, al.album_name AS ALBUM_NAME, al.album_year AS ALBUM_YEAR, al.introduction AS ALBUM_INTRODUCTION, al.company AS ALBUM_COMPANY, al.language AS ALBUM_LANGUAGE, GROUP_CONCAT(DISTINCT CONCAT(a.artist_name, '::', COALESCE(a.country, '')) ORDER BY sa.sort_order, a.id SEPARATOR '||') AS ARTIST_DATA, GROUP_CONCAT(DISTINCT st.style_name SEPARATOR '||') AS STYLE_NAMES, GROUP_CONCAT(DISTINCT l.content SEPARATOR '|||') AS LYRIC_CONTENTS FROM song s LEFT JOIN album al ON s.album_id = al.id LEFT JOIN song_artist sa ON s.id = sa.song_id LEFT JOIN artist a ON sa.artist_id = a.id LEFT JOIN song_style ss ON s.id = ss.song_id LEFT JOIN style st ON ss.style_id = st.id LEFT JOIN lyric l ON s.id = l.song_id WHERE s.file_path IN
#{p}
GROUP BY s.id, al.id

